 JSONObject searchRequest(String day)throws Exception{JSONObject from=new JSONObject().put("type","CITY").put("code","SEL"),to=new JSONObject().put("type","CITY").put("code","PAR");JSONArray legs=new JSONArray().put(new JSONObject().put("origin",from).put("destination",to).put("departureDate",day)).put(new JSONObject().put("origin",to).put("destination",from).put("departureDate",JSONObject.NULL).put("dateInterval",JSONObject.NULL));JSONObject request=new JSONObject().put("bookingFlow","REWARD").put("passengers",new JSONArray().put(new JSONObject().put("type","ADT"))).put("commercialCabins",new JSONArray().put("BUSINESS")).put("requestedConnections",legs);return new JSONObject().put("operationName",DETAIL).put("variables",new JSONObject().put("bookingFlow","REWARD").put("activeConnectionIndex",0).put("availableOfferRequestBody",request));}
